/// <summary>
/// A verify-only line the counter confirmed (instead of counting it).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountConfirmationRow
{
    real lineNumber;
    str  confirmedBy;
    str  confirmedAtUtc;

}

Method.Source:
[DataMemberAttribute('LineNumber')]
public real parmLineNumber(real _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('ConfirmedBy')]
public str parmConfirmedBy(str _value = confirmedBy)
{
    confirmedBy = _value;
    return confirmedBy;
}

[DataMemberAttribute('ConfirmedAtUtc')]
public str parmConfirmedAtUtc(str _value = confirmedAtUtc)
{
    confirmedAtUtc = _value;
    return confirmedAtUtc;
}
